    "theme": "Le voyage nocturne de la Mosquée sacrée à la Mosquée éloignée, la grande charte éthique (piété filiale, justice, mesure), l'honneur conféré aux fils d'Adam, et l'Esprit qui relève de l'ordre du Seigneur",
    "note_pedagogique": "La sourate s'ouvre sur l'isrāʾ, le voyage nocturne du Prophète de La Mecque à Jérusalem — subḥāna lladhī asrā. Elle contient l'une des plus belles chartes morales du Coran (v.23-39) : le culte exclusif lié à la bonté envers les parents, l'interdit du gaspillage, de l'infanticide, de la fraude, de l'arrogance. Elle culmine sur la dignité universelle : « Nous avons honoré les fils d'Adam. »",
