          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Rabbin'den umduğun rahmeti elde etmek için, hak sahiblerinden yüz çevirmek zorunda kalırsan, onlara hiç değilse tatlı bir söz söyle"
