      "ar": "أَوْ تُسْقِطَ السَّمَاءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِيَ بِاللَّهِ وَالْمَلَـٰئِكَةِ قَبِيلًا",
      "translit": "Aw tusqiṭa s-samāʾa kamā zaʿamta ʿalaynā kisafan aw taʾtiya billāhi wal-malāʾikati qabīlā",
