      "translit": "Quli dʿū llāha awi dʿū r-raḥmāna ayyan mā tadʿū falahu l-ʾasmāʾu l-ḥusnā walā tajhar biṣalātika walā tukhāfit bihā wabtaghi bayna dhālika sabīlā",
