    "declic_frequence": "karrama (honorer, ennoblir, racine ك-ر-م) fonde au v.70 la dignité humaine universelle : wa-laqad karramnā banī Ādam — « Nous avons certes honoré les fils d'Adam ». Non les croyants seulement, non un peuple : TOUS les descendants d'Adam, portés « sur terre et sur mer », pourvus de bonnes choses, préférés à beaucoup de créatures. La karāma, cette noblesse conférée par Dieu, précède tout mérite et fonde une éthique : chaque être humain, quel qu'il soit, porte un honneur inviolable donné d'en haut."
